function ProfileEditor({ id }: { id: string }) {
+  const { data } = useQuery({ queryKey: ['user', id], queryFn: () => fetchUser(id) });
+  // mirror the whole server object into local state "so we can edit it"
+  const [user, setUser] = useState(data);
+
+  const save = useMutation({
+    mutationFn: () => patchUser(id, user),
+    // no onSuccess: cache is never invalidated after the write
+  });
+
+  return (
+    <form onSubmit={() => save.mutate()}>
+      <input value={user?.name ?? ''} onChange={e => setUser(u => ({ ...u!, name: e.target.value }))} />
+      <button>Save</button>
+    </form>
+  );
+}
